mapper.select:
select * from message conversation_id in
#{conversationId}
and send_time >= #{quitTime}
order by id desc -- 只有当初始化登录时限制查询数量，增量更新不需要
limit 100

mapper.update:
update message
set send_status = #{sendStatus}
where file_id = #{fileId}

mapper.delete:
delete
from message
where conversation_id = #{conversationId}
  and sender_id = #{senderId}

delete
from message
where conversation_id = #{conversationId}
  and id = #{messageId}
